  const pipeline = new ReviewPipeline(
    template,
    context,
    adapters.git,
    adapters.poster,
    adapters.llm,
    adapters.sanitizer,
    adapters.logger,
    persona,
    config,
  );

  // Run — structured ID: bridgebuilder-YYYYMMDDTHHMMSS-hex4 (sortable + unique)
